// The brain: one call site for the project's judgement calls (build or not, ship or not, retire, model swaps). One
// call per decision on the brain model. The cached system prompt is the task (the persona bundle's `brain` prompt), the persona's charter (src/persona.ts:
// values and priorities; private, only its hash is public) and the project's facts and limits (brain/context.md,
// generated by scripts/brain-context.ts); the message carries the self-file (src/self.ts: what it can and can't do, its
// last decisions and what came of them, open risks) next to the input. Every decision is a signed `brain` log record
// carrying the model, the sha256 of the context, the persona file (null: the neutral default) and the self-file, the
// registry it ran under, the input's sha256 and the decision. Code still enforces every limit; the brain only chooses
// inside them. Everything in the input (ideas, specs, test logs, PR text) is DATA.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { z } from "zod";
import { type Call, llm } from "./llm.ts";
import { append, canonical } from "./log.ts";
import { model, registryInfo } from "./models.ts";
import { PERSONA, prompt, sys } from "./persona.ts";

const s = (max: number) => z.string().min(1).max(max);
const Vec = z.object({ base: z.number().int(), mult: z.number().int(), cap: z.number().int() });
const R = z.number().int().min(0).max(5);
/** The public rubric for build ideas (criteria: policy.ts RUBRIC, in the context). Score = the sum, 0-20. */
export const Rubric = z.object({ value: R, fit: R, clarity: R, originality: R });
export type Rubric = z.infer<typeof Rubric>;
/** The closest buildable version of an idea (a standalone game, a site change or a fee/split module), with its rubric. */
export const Variant = z.object({ target: z.enum(["game", "site", "module"]), title: z.string().min(1).max(120), spec: z.string().min(1).max(900), rubric: Rubric });
export type Variant = z.infer<typeof Variant>;
export const BrainOut = {
  build: z.object({ decision: z.enum(["build", "no-build"]), target: z.enum(["game", "site", "module"]).optional(), reason: s(400), risks: z.array(s(200)).max(5) }),
  verdict: z.object({ verdict: z.enum(["ship", "rework", "kill"]), reason: s(400), issues: z.array(s(200)).max(8) }),
  // a spec amendment the dev team's lead proposed (once per build): approved, it is the spec later verdicts check
  amend: z.object({ approve: z.boolean(), reason: s(400) }),
  retire: z.object({ retire: z.boolean(), reason: s(400) }),
  "model-swap": z.object({ approve: z.boolean(), reason: s(400) }),
  // understood and plain are for the idea's author (the reply and the site say them); reason is the judge's own note.
  // variant: the closest buildable version of an idea whose form can't be built, credited to its author (live mode)
  outcome: z.object({
    ideas: z.array(z.object({
      id: z.number().int(), decision: z.enum(["accept", "reject", "void"]), kind: z.enum(["fee", "build", "impossible"]), reason: s(200),
      title: z.string().max(120), params: Vec.nullable(), rubric: Rubric.nullable(),
      understood: s(200), plain: s(240), variant: Variant.nullable(),
    })).max(128),
  }),
  reward: z.object({ amountEth: z.number().min(0).max(100), reason: s(400) }), // ETH; code clamps it into the on-chain caps
  // what to improve next, from the self-file's open risks (no idea in the queue); a spec the dev team builds from
  improve: z.object({ improve: z.boolean(), risk: z.string().max(300), target: z.enum(["site", "module", "engine"]), title: z.string().max(60), spec: z.string().max(4000), rubric: Rubric, reason: s(400) }),
};
export type BrainKind = keyof typeof BrainOut;
export type BrainDecision<K extends BrainKind> = z.output<(typeof BrainOut)[K]>;

const sha = (t: string | Buffer) => createHash("sha256").update(t).digest("hex");
const text = readFileSync(new URL("../brain/context.md", import.meta.url));
export const CONTEXT = { text: text.toString("utf8"), sha256: sha(text) };

/** One stable system prompt for every kind (the task per kind, the persona's charter, then the project context), so the cacheable prefix is the same bytes for every decision; the output schema differs per kind and may still give each kind its own cache entry. */
export const SYSTEM = [
  sys("brain", prompt("brain")),
  "",
  "# Charter",
  PERSONA.charter,
  "",
  CONTEXT.text,
].join("\n");

/** The brain's call for one decision (pure; tryouts call it with a candidate model and no self-file). */
export const brainCall = <K extends BrainKind>(kind: K, input: unknown, id = model("brain"), self?: string): Call<(typeof BrainOut)[K]> => ({
  agent: "brain", model: id, system: SYSTEM, input: self === undefined ? { kind, input } : { kind, self, input }, schema: BrainOut[kind],
  cache: true, effort: "high", maxOutputTokens: 8000,
});

/** The signed record body of a decision. */
export const decisionRecord = <K extends BrainKind>(kind: K, input: unknown, out: { data: BrainDecision<K>; model: string; costUsd: number }, selfSha256: string, at = new Date()) => ({
  kind, model: out.model, contextSha256: CONTEXT.sha256, personaSha256: PERSONA.sha256, selfSha256, models: registryInfo(), inputSha256: sha(canonical(input)), decision: out.data, costUsd: out.costUsd, at: at.toISOString(),
});

/** Ask the brain, record the decision (signed `brain` record, ref `<kind>:<ref or input hash>`), return it. */
export async function decide<K extends BrainKind>(kind: K, input: unknown, ref?: string) {
  const self = await (await import("./self.ts")).currentSelf();
  const out = (await llm(brainCall(kind, input, model("brain"), self.text))) as { data: BrainDecision<K>; model: string; costUsd: number };
  const body = decisionRecord(kind, input, out, self.sha256);
  const rec = await append("brain", `${kind}:${ref ?? body.inputSha256.slice(0, 16)}`, body);
  return { ...body, seq: rec.seq };
}
